#include "ui/live_wallpaper.hpp"
#include <iostream>
using namespace aether;
class Host final:public ui::Surface{void paint(ui::Canvas& c)override{auto s=c.size();c.fill(ui::box(0,0,s.width,s.height),0x111111);}public:explicit Host(ui::Graphics& g):Surface(g){}};
void pump(int ms){auto end=GetTickCount64()+ms;do{MSG m{};while(PeekMessageW(&m,nullptr,0,0,PM_REMOVE)){TranslateMessage(&m);DispatchMessageW(&m);}Sleep(5);}while(GetTickCount64()<end);}
void check(bool ok,const char* reason){if(!ok)throw std::runtime_error(reason);}
std::vector<std::wstring> staticWallpaper(){win::ComPtr<IDesktopWallpaper> desktop;check(SUCCEEDED(CoCreateInstance(CLSID_DesktopWallpaper,nullptr,CLSCTX_ALL,IID_PPV_ARGS(&desktop))),"static wallpaper query unavailable");UINT count=0;check(SUCCEEDED(desktop->GetMonitorDevicePathCount(&count)),"wallpaper monitor query");std::vector<std::wstring> result;for(UINT i=0;i<count;++i){LPWSTR id=nullptr,path=nullptr;check(SUCCEEDED(desktop->GetMonitorDevicePathAt(i,&id)),"wallpaper monitor ID");auto hr=desktop->GetWallpaper(id,&path);result.push_back(id);CoTaskMemFree(id);check(SUCCEEDED(hr),"wallpaper path query");result.push_back(path?path:L"");CoTaskMemFree(path);}DESKTOP_WALLPAPER_POSITION fit{};COLORREF color=0;check(SUCCEEDED(desktop->GetPosition(&fit))&&SUCCEEDED(desktop->GetBackgroundColor(&color)),"wallpaper position query");result.push_back(std::to_wstring(fit));result.push_back(std::to_wstring(color));return result;}
int main(int argc,char**){SetProcessDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2);win::ComApartment com;try{
 if(argc>1){auto before=staticWallpaper();auto context=GetThreadDpiAwarenessContext();ui::Graphics g;ui::LiveWallpaper live(g);auto displays=win::monitors();for(int preset=1;preset<=3;++preset){check(live.update(preset,displays,{},false),"Explorer wallpaper host unavailable");pump(800);check(live.count()==displays.size()&&live.frames()>=3*displays.size(),"desktop scenes did not animate on all monitors");auto actual=live.surfaceBounds();check(actual.size()==displays.size(),"desktop surface bounds unavailable");for(std::size_t i=0;i<actual.size();++i)check(actual[i]==displays[i].bounds,"desktop surface does not match physical monitor bounds");check(AreDpiAwarenessContextsEqual(context,GetThreadDpiAwarenessContext()),"desktop hosting changed controller DPI context");std::cout<<"Desktop preset "<<preset<<": "<<live.count()<<" displays, "<<live.frames()<<" frames\n";}live.stop();check(before==staticWallpaper(),"Windows static wallpaper was modified");std::cout<<"PASS actual desktop hosting, three presets, DPI context and unchanged static wallpaper\n";return 0;}
 ui::Graphics g;Host host(g);check(host.create(L"Aether owned animation host",WS_POPUP,WS_EX_TOOLWINDOW,{150,150,750,550}),"host creation");host.show();
 auto monitors=win::monitors();check(!monitors.empty(),"no monitors");auto monitor=monitors.front();monitor.bounds={150,150,750,550};std::vector<win::Monitor> displays{monitor};ui::LiveWallpaper live(g);
 for(int preset=1;preset<=3;++preset){check(live.update(preset,displays,{},false,host.hwnd()),"scene creation");pump(500);check(live.count()==1&&live.frames()>=3,"scene did not animate");auto originalScene=FindWindowExW(host.hwnd(),nullptr,L"Aether.Surface.v3",nullptr);auto beforeWorkChange=live.frames();auto changedWork=displays;changedWork[0].work.top+=40;changedWork[0].work.bottom-=70;check(live.update(preset,changedWork,{},false,host.hwnd()),"work-area refresh failed");check(FindWindowExW(host.hwnd(),nullptr,L"Aether.Surface.v3",nullptr)==originalScene&&live.frames()>=beforeWorkChange,"Dock work-area change recreated the wallpaper or reset animation");
 check(live.update(preset,displays,{},true,host.hwnd()),"pause");pump(100);auto frames=live.frames();pump(300);check(live.frames()==frames,"paused animation kept drawing");
 win::Window cover;cover.bounds=monitor.bounds;check(live.update(preset,displays,{cover},false,host.hwnd()),"cover pause");pump(300);check(live.frames()==frames,"covered monitor kept drawing");
 check(live.update(preset,displays,{},false,host.hwnd()),"resume");pump(300);check(live.frames()>frames,"resume did not animate");}
 live.stop();check(live.count()==0&&FindWindowExW(host.hwnd(),nullptr,L"Aether.Surface.v3",nullptr)==nullptr,"owned child leaked");
 check(parseSettings("[behavior]\nanimatedWallpaper=999\n").animatedWallpaper==3,"unbounded preset");Config c;c.animatedWallpaper=2;check(parseSettings(serializeSettings(c)).animatedWallpaper==2,"preset not persisted");check(parseSettings("").animatedWallpaper==0,"legacy profile animates by default");
 std::cout<<"PASS three animated scenes, pause, cover, resume, child cleanup and profile bounds\n";return 0;
 }catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
